  "reports.signInBody": "ವಿವರವಾದ ಜ್ಯೋತಿಷ್ಯ, ಸಂಖ್ಯಾಶಾಸ್ತ್ರ, ರತ್ನ ಮತ್ತು ಭವಿಷ್ಯ ವರದಿಗಳು ಸೈನ್ ಇನ್ ಆದ ಸದಸ್ಯರಿಗೆ ಲಭ್ಯ. ನಿಮ್ಮದನ್ನು ರಚಿಸಲು ಸೈನ್ ಇನ್ ಮಾಡಿ ಅಥವಾ ಉಚಿತ ಖಾತೆ ರಚಿಸಿ.",
  "reports.unlockBody": "ವರದಿಗಳು ಪ್ರೀಮಿಯಂ ವೈಶಿಷ್ಟ್ಯ — ನಿಮ್ಮ ಜನ್ಮ ಕುಂಡಲಿಯಿಂದ ಸುಂದರವಾಗಿ ರೂಪಿಸಿದ, ಬಹು-ಪುಟಗಳ ಫಲಜ್ಯೋತಿಷ್ಯಗಳು. ಕೋಡ್‌ನೊಂದಿಗೆ, ಅಥವಾ Astropanth Plus ನೊಂದಿಗೆ ಇವನ್ನು ತೆರೆಯಿರಿ.",
