  "desktop.pitch": "Astropanth ನಿಮ್ಮ ಫೋನ್‌ಗಾಗಿ ನಿರ್ಮಿಸಲಾಗಿದೆ — ಅಸಲಿ ವೈದಿಕ (ನಿರಯನ) ಜ್ಯೋತಿಷ್ಯ ಮತ್ತು ಸಂಖ್ಯಾಶಾಸ್ತ್ರ, ನಿಮ್ಮ ಜೇಬಿನಲ್ಲಿ. ಇಲ್ಲಿ ಫ್ರೇಮ್‌ನಲ್ಲಿ ಲೈವ್ ಆಗಿ ಬಳಸಿ, ಅಥವಾ ದೈನಂದಿನ ಅಧಿಸೂಚನೆಗಳೊಂದಿಗೆ ಪೂರ್ಣ ಅನುಭವಕ್ಕಾಗಿ ಆ್ಯಪ್ ಪಡೆಯಿರಿ.",
