  "kundli.shareBody": "சூரியன் {sun} இல், சந்திரன் {moon} இல், நட்சத்திரம் {nakshatra}.",
  "kundli.shareMsg": "என் Astropanth ஜாதகம் ✨ {lagnaPart}சந்திரன் {moon} இல் ({nakshatra})\n\nஉங்கள் இலவச ஜாதகத்தைப் பெறுங்கள்: https://www.astropanth.com",
